; apx_vex.asm -- APX EVEX promotion of VEX GPR instructions (Phase 4c)
;
; Environment
;	Assembly-time only: nothing here is executed (no APX processor is public
;	yet). fasmg assembles each instruction inside VIRTUAL and compares the
;	bytes (reference: llvm-mc 23, generated by tests/iset/_apx_diff.py; the
;	same instructions pass LLVM's andn, bextr, blsi, blsmsk, blsr, bmi2,
;	bzhi, cmpccxadd, kmov and amx-tile Intel-syntax tests through
;	tests/iset/_apx_corpus.py); a mismatch stops assembly with 'encoding
;	mismatch'. The failure cases at the end are each assembled alone by
;	_run.ps1 (-i"FAIL=n") and must stop with the quoted message.
;	By hand:  fasm2 apx_vex.asm apx_vex.bin
;
; What is new (spec 355828 3.1.2.3.2)
;	BMI1/BMI2, CMPccXADD, KMOV* and AMX's ldtilecfg/sttilecfg/tileload*/
;	tilestored keep their map and opcode in an EVEX form that can address
;	r16-r31: 62 [~R3 ~X3 ~B3 ~R4 B4 mmm] [W ~vvvv ~X4 pp] [0 0 L 0 ~V4 NF 0 0].
;	AVX_512.store_instruction takes it for instructions marked APX_PROMOTED
;	(VEX_GPR implies it, except XOP; KMOV and AMX pass it through
;	AVX.store_apx_instruction) when an operand is r16-r31, when {nf} is
;	given (andn, bextr, blsi, blsmsk, blsr, bzhi; through layers), or for
;	{evex} with APX_F on. Failure modes this file guards against:
;	- B4 for a GPR in r/m or as base, X4 (the inverted U bit) for a GPR
;	  index, R4/V4 for GPRs in ModRM.reg and vvvv;
;	- the vector X bit (rm bit 4 for xmm16+) must not fire for a GPR;
;	- disp8 is not scaled (N = 1): [rax+40h] keeps 40h;
;	- the VEX forms keep their bytes, also with "use evex" and no APX_F;
;	- VEX instructions without an EVEX form (vaesimc) and XOP are not
;	  promoted (apx_rex2.asm).
;
; FAIL 1: 'APX_F or higher required'
; FAIL 2: 'APX_F or higher required'
; FAIL 3: 'APX_F or higher required'
; FAIL 4: 'bits64 or higher required'
; FAIL 5: 'extended register not supported: [r16,rax]'

macro expect bytes*, line&
	local n, got, k, want
	virtual at 0
		line
		n = $
		load got:n from 0
	end virtual
	virtual at 0
		db bytes
		k = $
		load want:k from 0
	end virtual
	if n <> k | got <> want
		display 'FAIL: ', `line, 13, 10
		err 'encoding mismatch'
	end if
end macro

use64

if ~ defined FAIL

	use everything
	expect <0C4h,0E2h,60h,0F2h,0C1h>, andn eax, ebx, ecx
	expect <62h,0EAh,0F4h,00h,0F2h,0C2h>, andn r16, r17, r18
	expect <62h,0EAh,78h,08h,0F2h,44h,0ACh,08h>, andn r16d, eax, [r20+r21*4+8]
	expect <0C4h,0E2h,60h,0F2h,40h,40h>, andn eax, ebx, [rax+40h]
	expect <62h,0F2h,64h,0Ch,0F2h,0C1h>, andn {nf} eax, ebx, ecx
	expect <62h,0F2h,64h,08h,0F2h,0C1h>, {evex} andn eax, ebx, ecx
	expect <62h,0EAh,0ECh,00h,0F7h,01h>, bextr r16, [r17], r18
	expect <62h,0F2h,74h,0Ch,0F7h,0C3h>, bextr {nf} eax, ebx, ecx
	expect <62h,0FAh,0FCh,00h,0F3h,0D9h>, blsi r16, r17
	expect <62h,0F2h,7Ch,0Ch,0F3h,1Bh>, blsi {nf} eax, [rbx]
	expect <62h,0DAh,04h,04h,0F3h,0D6h>, blsmsk {nf} r31d, r30d
	expect <62h,0F2h,0F8h,00h,0F3h,0Ch,60h>, blsr r16, [rax+r20*2]
	expect <62h,0EAh,0ECh,04h,0F5h,0C1h>, bzhi {nf} r16, r17, r18
	expect <62h,0F2h,0FCh,00h,0F5h,03h>, bzhi rax, [rbx], r16
	expect <62h,0EAh,0F7h,00h,0F6h,0C2h>, mulx r16, r17, r18
	expect <62h,0FAh,0FFh,00h,0F5h,01h>, pdep rax, r16, [r17]
	expect <62h,0E2h,7Eh,08h,0F5h,0C3h>, pext r16d, eax, ebx
	expect <62h,0EBh,0FFh,08h,0F0h,01h,05h>, rorx r16, [r17], 5
	expect <62h,0EAh,0EEh,00h,0F7h,0C1h>, sarx r16, r17, r18
	expect <62h,0FAh,65h,08h,0F7h,00h>, shlx eax, [r16], ebx
	expect <62h,4Ah,97h,00h,0F7h,0FEh>, shrx r31, r30, r29
	expect <62h,0F2h,0E7h,08h,0F6h,0C1h>, {evex} mulx rax, rbx, rcx
	expect <62h,0FAh,0E5h,08h,0E6h,00h>, cmpbexadd [r16], rax, rbx
	expect <62h,0E2h,75h,00h,0E7h,00h>, cmpaxadd [rax], r16d, r17d
	expect <62h,0FAh,0C9h,00h,0E4h,04h,0ECh>, cmpexadd [r20+r21*8], rax, r22
	expect <62h,0F2h,0F5h,08h,0E4h,18h>, {evex} cmpexadd [rax], rbx, rcx
	expect <62h,0F9h,7Ch,08h,92h,0C8h>, kmovw k1, r16d
	expect <62h,0E1h,7Fh,08h,93h,0C1h>, kmovd r16d, k1
	expect <62h,0F9h,0FFh,08h,92h,0C8h>, kmovq k1, r16
	expect <62h,0F9h,7Dh,08h,90h,10h>, kmovb k2, [r16]
	expect <62h,0F9h,0F8h,08h,91h,1Ch,11h>, kmovq [r17+r18], k3
	expect <62h,0F1h,7Ch,08h,92h,0C8h>, {evex} kmovw k1, eax
	expect <62h,0FAh,7Ch,08h,49h,00h>, ldtilecfg [r16]
	expect <62h,0FAh,7Dh,08h,49h,41h,40h>, sttilecfg [r17+40h]
	expect <62h,0FAh,7Bh,08h,4Bh,04h,08h>, tileloadd tmm0, [r16+r17]
	expect <62h,0F2h,79h,08h,4Bh,0Ch,20h>, tileloaddt1 tmm1, [rax+r20]
	expect <62h,0FAh,7Ah,08h,4Bh,14h,48h>, tilestored [r16+r17*2], tmm2
	expect <62h,0F2h,7Fh,08h,4Bh,04h,18h>, {evex} tileloadd tmm0, [rax+rbx]
	expect <0C4h,0E2h,60h,0F2h,0C1h>, andn eax, ebx, ecx
	expect <0C5h,0F8h,92h,0C8h>, kmovw k1, eax
	expect <0C4h,0E2h,7Bh,4Bh,04h,18h>, tileloadd tmm0, [rax+rbx]
	expect <62h,0FAh,7Fh,08h,4Bh,04h,00h>, tileloadd tmm0, [r16,rax]	; fasm2 [base, index] syntax: bytes as for [base+index]
	expect <62h,0FAh,7Ah,08h,4Bh,0Ch,08h>, tilestored [r16,r17], tmm1	; fasm2 [base, index] syntax: bytes as for [base+index]

	; without APX_F, {evex} ("use evex", as for AVX-512 code) leaves the
	; VEX forms alone
	use AMD64, AVX512, BMI1, BMI2, evex
	expect <0C4h,0E2h,60h,0F2h,0C1h>, andn eax, ebx, ecx
	expect <0C4h,0E2h,0F3h,0F6h,0C1h>, mulx rax, rcx, rcx

else if FAIL = 1
	use i386, x64, BMI1
	andn r16, rax, rbx

else if FAIL = 2	; NF needs the EVEX form
	use i386, x64, BMI1
	andn {nf} eax, ebx, ecx

else if FAIL = 3
	use i386, x64, AVX512BW
	kmovd k1, r16d

else if FAIL = 4
	use everything
	use32
	andn eax, ebx, r16d

else if FAIL = 5	; MPX's [base, index] still refuses them
	use everything
	bndldx bnd0, [r16,rax]

end if